function CatHouseExploreCatListPopup:RefreshPanel()
    self:InitCatList()
    self:UpdateTeamNum(checkNumber(table.count(CatHouseExploreMgr.listCatsTeam)))
end

function CatHouseExploreCatListPopup:InitCatList()
    local len = checkNumber(#self.catList)
    if not self.CatList.IsListViewInit then
        self.CatList:InitListView(len, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.CatList, len)
    end
end

function CatHouseExploreCatListPopup:OnGetItemByIndex(cell, index)
    if index < 0 then return end
    ---@type Engine.Modules.LuaBehaviour
    local node = GetLuaBehaviour(cell.gameObject, CatHouseListBtnNodeEnvPath)
    ---@type CatHouseListBtnNode
    local nodeEnv = node.Env
    if isNull(nodeEnv) then return cell end
    local position         = index + 1
    nodeEnv:SetCallback(Bind(self, self.OnClickCatNodeAction))
    nodeEnv:FreshCommonUI(self.catList[position])
    nodeEnv:FreshExploreUI(self.attributeId, self.requireData)
    self:RefreshCellSelectStatus(nodeEnv)
    return cell
end

function CatHouseExploreCatListPopup:GetCatCellSelectNode(node) 
    local transNode = node.controller.gameObject.transform:Find("AnimRoot/BtnNode/CatDetails/ImgCollect")
    if not IsNull(transNode) then
        return transNode
    end
    return nil
end

function CatHouseExploreCatListPopup:RefreshCellSelectStatus(nodeEnv)
    if isNull(nodeEnv) then return end
    local catData = nodeEnv.catData
    local transSelectNode = self:GetCatCellSelectNode(nodeEnv)
    local isInList, index = self:CheckCatInList(catData)
    if not IsNull(transSelectNode) then
        KTool.SetActive(transSelectNode.gameObject, isInList)
    end
end

function CatHouseExploreCatListPopup:OnClickCatNodeAction(catData)
    local isInList, index = self:CheckCatInList(catData)
    if isInList then
        CatHouseExploreMgr:RemoveExploreTeamMember(index)
    else
        CatHouseExploreMgr:InsertExploreTeamMember(catData)
    end
    self:UpdateTeamNum(checkNumber(table.count(CatHouseExploreMgr.listCatsTeam)))
end

function CatHouseExploreCatListPopup:RefreshCatsSelectStatus(catData, luaB)
    local isInList, index = self:CheckCatInList(catData)
    local transSelectNode = self:GetCatCellSelectNode(luaB.Env)
    if not IsNull(transSelectNode) then
        KTool.SetActive(transSelectNode.gameObject, isInList)
    end
end

function CatHouseExploreCatListPopup:CheckCatInList(catData)
    if isNull(catData) then return false end
    if isNull(CatHouseExploreMgr.listCatsTeam) then CatHouseExploreMgr.listCatsTeam = {} end
    local catUid = catData.id
    for i = 1, #CatHouseExploreMgr.listCatsTeam do
        local value = CatHouseExploreMgr.listCatsTeam[i]
        if checkInt(value.id) == checkInt(catUid) then return true, i end
    end
    return false
end

