function CatHouseExploreCatListPopup:UpdateTeamNum(value)
    if not IsNull(self.TextNumber) then
        self.TextNumber.text = checkString(string.format("%s/%s",checkString(value), checkString(CatHouseExploreMgr.EXPLORE_TEAM_CAT_MAX)))
    end
end

function CatHouseExploreCatListPopup:FreshUI()
    xTry(function()
        self:FreshFilterNode()
    end)
end

function CatHouseExploreCatListPopup:FreshFilterNode()
    ---@type UICommonFilterMB
    self.filterNode = CfUtils.GetLuaScr(self.CommonFilterNode.gameObject, UICommonFilterMBNode)
    if isNull(self.filterNode) then return end
    self.filterNode:SetFilterClass()
    self.filterNode:SetExtraParams(checkNumber(self.catHouseHomeDojo.partyCatId))
    self.filterNode:SetCallback(self.catList, Bind(self, self.OnClickFilterNode), Constants.UISortType.CatHouseExplore)
    self.filterNode:RestoreState("CatHouseExploreCatListPopup", Bind(self, self.OnClickFilterNode))
end

function CatHouseExploreCatListPopup:OnClickFilterNode(dataList)
    self.catList = dataList
    local asc = checkBool(self.filterNode.sortTypeList[self.filterNode.selectIndex].asc)
    self.catList = CatHouseExploreMgr:SortCatsByAttributeType(self.catList, self.attributeId, asc)
    self:RefreshPanel()
end

return CatHouseExploreCatListPopup